const descs = [];
for (const r of REST) { descs.push({ key_id: r[0], description: r[1] }); }
for (const s of SUBJ) {
  descs.push({ key_id: s[0], description: 'Subject line of the ' + s[1] + ' email. Shown in the inbox next to the sender, never inside the email body. Keep it under about 60 characters so it is not cut off in mobile inboxes, and keep the emoji if the source has one.' });
}
for (const i of IMG) {
  if (i[2] === 'l') {
    descs.push({ key_id: i[0], description: 'Image style picker in the chat UI - name of the "' + i[1] + '" style chip. Keep it to one or two words; the chips are narrow and the text does not wrap.' });
  } else {
    descs.push({ key_id: i[0], description: 'Image style picker - the instruction sent to the image model when the user picks the "' + i[1] + '" style. Never shown to the user. Translate the descriptive wording but keep the technical rendering terms (lighting, shading, render, texture and similar) recognisable, since they steer the model.' });
  }
}

const out = [];
for (const sid of Object.keys(LINKS)) {
  out.push({ json: { label: 'screenshot ' + sid, method: 'PUT', url: 'https://api.lokalise.com/api2/projects/' + PROJECT + '/screenshots/' + sid, body: { key_ids: LINKS[sid] } } });
}
for (let i = 0; i < descs.length; i += 70) {
  const chunk = descs.slice(i, i + 70);
  out.push({ json: { label: 'descriptions ' + i + '-' + (i + chunk.length - 1), method: 'PUT', url: 'https://api.lokalise.com/api2/projects/' + PROJECT + '/keys', body: { keys: chunk } } });
}
return out;

const reqs = $('Config').all();
const res = $input.all();
const rows = [];
let ok = 0;
for (let i = 0; i < res.length; i++) {
  const r = res[i].json || {};
  const meta = (reqs[i] && reqs[i].json) ? reqs[i].json : {};
  const body = r.body || {};
  const good = r.statusCode === 200;
  if (good) { ok++; }
  let detail = '';
  if (body.screenshot) { detail = 'keys=' + ((body.screenshot.key_ids || []).length); }
  else if (body.keys) { detail = 'keys_updated=' + body.keys.length + ' errors=' + ((body.errors || []).length); }
  else { detail = JSON.stringify(body).slice(0, 200); }
  rows.push({ label: meta.label, status: r.statusCode, detail: detail });
}
return [{ json: { ok: ok, total: rows.length, rows: rows } }];
